import{z as i,x as s,o as e,c as n,q as A,j as l,D as E,d as t,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"多 LoRA 的调度","description":"","frontmatter":{"title":"多 LoRA 的调度","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-multi-lora.md","filePath":"llm/sch-multi-lora.md","lastUpdated":1791063341000}'),d={name:"llm/sch-multi-lora.md"};function h(p,a,D,m,C,_){const r=s("Mermaid");return e(),n("div",null,[a[2]||(a[2]=A('<h1 id="多-lora-的调度" tabindex="-1">多 LoRA 的调度 <a class="header-anchor" href="#多-lora-的调度" aria-label="Permalink to &quot;多 LoRA 的调度&quot;">​</a></h1><div class="epigraph"><p>一份基座、许多适配器之后，调度器多管一种资源：它的驻留由请求热度决定，它的抖动与 KV 抖动同构。</p><footer>—— 据 Chen et al., MLSys 2024（Punica）与 Sheng et al., MLSys 2024（S-LoRA）整理</footer></div><p><a href="/llm/sch-pd-disaggregated">上一课</a>把阶段拆成池子；本课把「模型」这一维打开：一份常驻基座、几十上千个 LoRA 适配器，请求各带各的 adapter id。服务形态与特制核主干已有（<a href="/llm/multi-lora-serving">多 LoRA 服务</a>、<a href="/llm/slora">S-LoRA 分页适配器</a>、<a href="/llm/lorax-serving">LoRAX</a>）；本课只写调度器视角：驻留集怎么管、批怎么跨适配器混、配额怎么落到适配器粒度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>适配器是第三种资源：基座权重常驻（人人共享），KV 按请求计费，适配器按<strong>热度</strong>进出显存。<span class="marginnote">术语翻译：LoRA 就是「不重训整个模型，只训两个很小的矩阵，把它们的乘积当成对原权重的微调补丁」——基座权重冻结不动，换一个补丁就像给同一个模型换一种口音或专长。补丁比原模型小几个数量级，所以一份基座能同时挂几百上千个。</span>调度器新增两个决定。第一，驻留集：GPU 上放哪些 \\(A\\)、\\(B\\)？冷适配器请求的 TTFT 里含一次加载（主存到显存，最坏是磁盘）；驻留集换得太勤，GPU 在搬矩阵不产 token——与抢占抖动同构的适配器抖动。第二，批的构成：核能否在同一次前向里对多个适配器做 gather 乘法？不能的话，「多租户」退化成同适配器分组批，不同租户的请求无法同批，连续批的收益按租户碎掉。</p><h3 id="驻留当缓存管" tabindex="-1">驻留当缓存管 <a class="header-anchor" href="#驻留当缓存管" aria-label="Permalink to &quot;驻留当缓存管&quot;">​</a></h3><p>驻留集是标准的缓存问题：键是 adapter id，值是权重增量，容量是显存里划给适配器的池。<span class="marginnote">直觉类比：适配器驻留集就像厨房的调料架——台面（显存）有限，常用的盐糖酱油（热适配器）常驻手边，不常用的收进储藏室（主存甚至磁盘）；做菜中途跑一趟储藏室，上菜自然就慢（TTFT 里多出一次加载）。LRU 策略就是「最久没人点的调料先收起来」，但正在锅里用的（批内租约）谁也不许动。</span>策略用带热度计数的 LRU：滑窗请求数决定去留，热的钉住，正在批内的适配器有租约不可换出；可预测的时段流量做预载（早高峰前把办公租户的适配器提上来）。加载是<strong>无损</strong>的：权重增量可再生，回来不需要重算——比 KV 换出便宜在正确性自动恢复，贵在单个体积可能比一条 KV 大。路由按适配器亲和：同 id 的请求导向已驻留的副本；代价与下一课的缓存感知路由完全同构——亲和集中与负载均衡打架。</p>',7)),(e(),l(o,null,{default:E(()=>[B(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9Aadapter%20id%22%5D%20--%3E%20RES%7B%22%E9%A9%BB%E7%95%99%E9%9B%86%E4%B8%AD%22%7D%0A%20%20RES%20--%3E%7C%E5%91%BD%E4%B8%AD%7C%20MIX%5B%22%E8%BF%9B%E6%B7%B7%E5%90%88%E6%89%B9%EF%BC%9Agather%20%E6%A0%B8%E6%8C%89%20id%20%E4%B9%98%22%5D%0A%20%20RES%20--%3E%7C%E6%9C%AA%E5%91%BD%E4%B8%AD%7C%20LOAD%5B%22%E5%8A%A0%E8%BD%BD%E8%B7%AF%E5%BE%84%EF%BC%9ATTFT%20%E5%8A%A0%E4%B8%80%E6%AC%A1%E5%8A%A0%E8%BD%BD%E6%97%B6%E9%97%B4%22%5D%0A%20%20LOAD%20--%3E%20POOL%7B%22%E9%80%82%E9%85%8D%E5%99%A8%E6%B1%A0%E6%9C%89%E7%A9%BA%E9%97%B4%22%7D%0A%20%20POOL%20--%3E%7C%E6%9C%89%7C%20PIN%5B%22%E8%BD%BD%E5%85%A5%E5%B9%B6%E8%AE%A1%E5%85%A5%20LRU%22%5D%0A%20%20POOL%20--%3E%7C%E6%97%A0%7C%20EVICT%5B%22%E6%8C%89%E7%83%AD%E5%BA%A6%E6%8D%A2%E5%87%BA%E6%9C%80%E5%86%B7%E8%80%85%EF%BC%8C%E4%B8%8D%E7%A2%B0%E6%89%B9%E5%86%85%E7%A7%9F%E7%BA%A6%22%5D%0A%20%20EVICT%20--%3E%20PIN%0A%20%20PIN%20--%3E%20MIX%0A%20%20MIX%20--%3E%20OUT%5B%22%E8%AE%B0%E8%B4%A6%EF%BC%9A%E6%8C%89%E9%80%82%E9%85%8D%E5%99%A8%E7%B2%92%E5%BA%A6%E5%87%BA%E8%B4%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>同构映射</strong>：把适配器驻留集映射成标准缓存问题——键是 adapter id、值是权重增量、容量是显存池——策略直接取带热度计数的 LRU，加批内租约与可预测时段预载；加载无损，免去重算那本账。第二刀是核能力决定论：gather 核能异构则批可跨租户混，调度自由度由引擎设计给死，不是调参变量。配额与路由分别落到租户粒度与亲和问题，与 KV、抢占课程共用同一套词汇。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>批内异构靠核：Punica 的 SGMV 把不同适配器的低秩乘收进一次访存，S-LoRA 把适配器权重与 KV 放进统一分页池。这两个机制决定调度器的自由度：核支持异构，批就能跨租户混；不支持，调度器只能按适配器分组，碎片化损失是引擎设计决定的，不是调参能救的。配额与隔离落到适配器粒度：租户与适配器一一对应时，每适配器的并发上限、KV 水位、优先级就是租户配额（本课程最后的隔离课把这层收拢）。一条硬边界必须重申：<strong>KV 不可跨适配器复用</strong>——同一段前缀在不同适配器下算出的 K、V 不同（<a href="/llm/multi-lora-serving">多 LoRA 服务</a> 已钉），前缀缓存的命中统计必须按适配器分键，否则统计与正确性双错。<span class="marginnote">常见误区：初学者容易以为共享前缀的 KV 在不同适配器间可以复用，反正前缀一样。不行——补丁改变了每一层的输出，同一段前缀在不同补丁下算出的 K、V 就是不同的数；复用了，正确性悄悄坏掉，而且输出上往往一时看不出来，是最难查的那种错。</span></p><p>为什么一个小补丁就能换风格？看一次前向里的结构：</p>',5)),(e(),l(o,null,{default:E(()=>[B(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20x%22%5D%20--%3E%20W%5B%22%E5%9F%BA%E5%BA%A7%E6%9D%83%E9%87%8D%20W%EF%BC%9A%E5%86%BB%E7%BB%93%E4%B8%8D%E5%8A%A8%EF%BC%8C%E4%BA%BA%E4%BA%BA%E5%85%B1%E4%BA%AB%22%5D%0A%20%20X%20--%3E%20A%5B%22%E5%B0%8F%E7%9F%A9%E9%98%B5%20A%EF%BC%9Ar%20%C3%97%20in%22%5D%0A%20%20A%20--%3E%20B%5B%22%E5%B0%8F%E7%9F%A9%E9%98%B5%20B%EF%BC%9Aout%20%C3%97%20r%22%5D%0A%20%20W%20--%3E%20ADD%5B%22x%C2%B7W%20%E5%8A%A0%E4%B8%8A%20x%C2%B7A%C2%B7B%22%5D%0A%20%20B%20--%3E%20ADD%0A%20%20ADD%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%EF%BC%9A%E5%90%8C%E4%B8%80%E6%A8%A1%E5%9E%8B%E7%9A%84%E4%B8%8D%E5%90%8C%E5%8F%A3%E9%9F%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<p><span class="marginnote">体积账：秩 16、hidden 4096、32 层、QKVO 加 MLP 全目标、fp16，单个适配器约 80 MB。一千个就是 80 GB——比多数 7B 基座本身还大。这正是 S-LoRA 把适配器放进统一分页池、多数驻留主存的原因，也是「数千适配器」的数字总伴着「多数冷备」小字的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>热且稳定的租户可以把适配器合并进基座权重，省一份间接与批内复杂度，但失去秒级下线与更新（<a href="/llm/adapter-hot-swap">适配器热更新</a> 的迭代边界语义）；频繁切换、长尾租户不要合并。调度参数要与 KV 池联调：给适配器多留显存，KV 池就小，decode 并发上限下降——两种资源在同一张卡上争地皮，按租户的 KV 足迹与适配器热度联评定。多秩混合、张量并行下的适配器广播等细节以各自论文与引擎文档为准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>适配器是按热度进出的第三种资源：驻留集是缓存问题，抖动与抢占抖动同构。</li><li>加载是无损的（可再生、不需重算），单个体积可观；LRU 加租约是默认策略。</li><li>批内跨适配器靠 gather 核；核不支持时多租户退化为分组批。</li><li>路由按 adapter id 亲和，代价结构与缓存感知路由相同。</li><li>KV 不可跨适配器复用，缓存键与统计必须按适配器分。</li><li>出处：Chen et al., Punica, MLSys 2024，arXiv:2310.18547；Sheng et al., S-LoRA, MLSys 2024，arXiv:2311.03285。</li></ul>',5))])}const L=i(d,[["render",h]]);export{u as __pageData,L as default};
